#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* toHex(int32_t num) {
    char* out = (char*)malloc(9);
    const char* digits = "0123456789abcdef";
    uint32_t u = (uint32_t)num;
    int len = 0;
    if (u == 0) { out[0] = '0'; out[1] = '\0'; return out; }
    while (u != 0) {
        out[len++] = digits[u & 0xF];
        u >>= 4;
    }
    for (int i = 0; i < len / 2; ++i) {
        char tmp = out[i]; out[i] = out[len - 1 - i]; out[len - 1 - i] = tmp;
    }
    out[len] = '\0';
    return out;
}

