import sys, json

class Solution:
    def toHex(self, num: int) -> str:
        if num == 0:
            return "0"
        if num < 0:
            num &= 0xffffffff
        digits = "0123456789abcdef"
        out = []
        while num:
            out.append(digits[num & 0xf])
            num >>= 4
        return "".join(reversed(out))

