function toHex(num) {
    if (num === 0) return "0";
    let u = num >>> 0;
    const digits = "0123456789abcdef";
    const out = [];
    while (u !== 0) {
        out.push(digits[u & 15]);
        u >>>= 4;
    }
    return out.reverse().join("");
}

